class LevelDefinition {
  const LevelDefinition({
    required this.name,
    required this.rows,
    required this.colorRuns,
    this.paintOrder = LevelPaintOrder.centerOut,
    this.cellRows = const [],
    this.gridRows = LevelData.rows,
    this.gridCols = LevelData.cols,
    this.hasChainDecoration = false,
  });

  final String name;
  final List<String> rows;
  final List<LevelColorRun> colorRuns;
  final LevelPaintOrder paintOrder;
  final List<String> cellRows;
  final int gridRows;
  final int gridCols;
  final bool hasChainDecoration;
}

class LevelColorRun {
  const LevelColorRun(this.colorId, this.amount);

  final int colorId;
  final int amount;
}

enum LevelPaintOrder {
  centerOut,
  edgeIn,
  rowSnake,
  columnSnake,
  diagonal,
  antiDiagonal,
}

enum SilhouetteCellType { outside, outline, inside }

