  static List<PixelCell> createCells({
    int? levelIndex,
    LevelDefinition? level,
  }) {
    final lvl = level ?? levelAt(levelIndex ?? 0);
    final isLevel52 = levelIndex == 51;
    final isLevel53 = levelIndex == 52;
    List<PixelCell> cells = [];
    final rows = lvl.cellRows;
    if (rows.isEmpty) return [];
    for (int r = 0; r < rows.length; r++) {
      for (int c = 0; c < rows[r].length; c++) {
        final char = rows[r][c];
        if (isLevel53) {
          int colorId = 0;
          switch (char) {
            case 'A': colorId = 1; break;     // Red
            case 'B': colorId = 139; break;   // Crimson / Kilic Yakut Kirmizi
            case 'C': colorId = 180; break;   // Sokak Tugla Kirmizisi
            case 'D': colorId = 183; break;   // Sokak Golge Kirmizisi
            case 'E': colorId = 12; break;    // Siyah
            case 'F': colorId = 15; break;     // Slate / Dark Grey
            case 'G': colorId = 13; break;     // Gri / Light Grey
            case 'H': colorId = 11; break;     // White
            case 'I': colorId = 23; break;     // Orange
          }
          cells.add(PixelCell(row: r, col: c, targetColorId: colorId));

        } else if (lvl.name == 'Ucak') {
          int colorId = 0;
          switch (char) {
            case 'S': colorId = 12; break;
            case 'M': colorId = 132; break;
            case 'B': colorId = 11; break;
            case 'K': colorId = 1; break;
            case 'G': colorId = 13; break;
            case 'Y': colorId = 3; break;
          }
          cells.add(PixelCell(row: r, col: c, targetColorId: colorId));
        } else if (lvl.name == 'Tir') {
          int colorId = 0;
          switch (char) {
            case 'S': colorId = 12; break;
            case 'M': colorId = 132; break;
            case 'G': colorId = 13; break;
            case 'B': colorId = 11; break;
            case 'A': colorId = 57; break;
          }
          cells.add(PixelCell(row: r, col: c, targetColorId: colorId));
        } else if (lvl.name == 'Kaleci') {
          int colorId = 0;
          switch (char) {
            case 'S': colorId = 12; break;
            case 'K': colorId = 1; break;
            case 'T': colorId = 42; break;
            case 'B': colorId = 11; break;
          }
