  static LevelDefinition levelAt(int index) {
    if (index < 0 || index >= levels.length) return levels.last;
    return levels[index];
  }

  static Iterable<PaintCartridge> cartridgesForLevel(int index) {
    final level = levelAt(index);
    final colorIds = level.colorRuns.map((r) => r.colorId).toSet();
    return cartridges.where((c) => colorIds.contains(c.colorId));
  }

